   531  /*
   532   * searches a config_line linked list for a match
   533   */
   534  static int
   535  run_config_handler(struct config_line *lptr,
   536                     const char *token, char *cptr, int when)
   537  {
   538      char           *cp;
   539
   540      netsnmp_assert(token);
   541
   542      lptr = read_config_find_handler(lptr, token);
   543      if (lptr != NULL) {
   544          if (when == EITHER_CONFIG || lptr->config_time == when) {
   545              char tmpbuf[1];
   546              DEBUGMSGTL(("read_config:parser",
   547                          "Found a parser.  Calling it: %s / %s\n", token,
   548                          cptr));
   549              /*
   550               * Make sure cptr is non-null
   551               */
   552              if (!cptr) {
   553                  tmpbuf[0] = '\0';
   554                  cptr = tmpbuf;
   555              }
   556
   557              /*
   558               * Stomp on any trailing whitespace
   559               */
   560              cp = cptr[0] ? &(cptr[strlen(cptr)-1]) : cptr;
   561              while ((cp > cptr) && isspace((unsigned char)(*cp))) {
   562                  *(cp--) = '\0';
   563              }
   564              if (lptr->parse_line1)
   565                  lptr->parse_line1(token, cptr);
   566              else
   567                  lptr->parse_line2(token, cptr);
   568          }
   569          else
   570              DEBUGMSGTL(("9:read_config:parser",
   571                          "%s handler not registered for this time\n", token));
   572      } else if (when != PREMIB_CONFIG &&
   573                 !netsnmp_ds_get_boolean(NETSNMP_DS_LIBRARY_ID,
   574                                         NETSNMP_DS_LIB_NO_TOKEN_WARNINGS)) {
   575          netsnmp_config_warn("Unknown token: %s.", token);
   576          return SNMPERR_GENERR;
   577      }
   578      return SNMPERR_SUCCESS;
   579  }
