   668  void
   669  netsnmp_config_remember_in_list(char *line,
   670                                  struct read_config_memory **mem)
   671  {
   672      if (mem == NULL)
   673          return;
   674
   675      while (*mem != NULL)
   676          mem = &((*mem)->next);
   677
   678      *mem = SNMP_MALLOC_STRUCT(read_config_memory);
   679      if (*mem != NULL) {
   680          if (line)
   681              (*mem)->line = strdup(line);
   682      }
   683  }
   684
   685  void
   686  netsnmp_config_remember_free_list(struct read_config_memory **mem)
   687  {
   688      struct read_config_memory *tmpmem;
   689      while (*mem) {
   690          SNMP_FREE((*mem)->line);
   691          tmpmem = (*mem)->next;
   692          SNMP_FREE(*mem);
   693          *mem = tmpmem;
   694      }
   695  }
   696
   697  void
   698  netsnmp_config_process_memory_list(struct read_config_memory **memp,
   699                                     int when, int clear)
   700  {
   701
   702      struct read_config_memory *mem;
   703
   704      if (!memp)
   705          return;
   706
   707      mem = *memp;
   708
   709      while (mem) {
   710          DEBUGMSGTL(("read_config:mem", "processing memory: %s\n", mem->line));
   711          snmp_config_when(mem->line, when);
   712          mem = mem->next;
   713      }
   714
   715      if (clear)
   716          netsnmp_config_remember_free_list(memp);
   717  }
